text:
:root {
  user-select: none;

  &:-moz-locale-dir(rtl) {
    direction: rtl;
  }

  &[lwtheme] body {
    color-scheme: light-dark;
  }
}

:root,
body {
  margin: 0;
  padding: 0;
  block-size: 100%;
  inline-size: 100%;
  overflow: clip;
}

body {
  display: flex;
  flex-direction: column;
}
